-- STAGING ONLY 477: contain the one-shot runtime after UID632 transport/import while operation completeness is repaired.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-477-contain-after-uid632',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827026000') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827026000') OR NOT EXISTS(SELECT 1 FROM public.ai_email_intake WHERE provider_uid='imap_uid:632' AND status='vehicle_updated') OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE stock_number_normalized='13000776' AND job_card_number='J139125495') THEN RAISE EXCEPTION 'PDC_477_TARGET_OR_UID632_IMPORT_MISMATCH';END IF;END $g$;
UPDATE public.pdc_email_monitor_pilot SET enabled=false,outbound_email_enabled=false,automatic_rule_application=false,automatic_authenticated_jobcards=false,updated_at=clock_timestamp() WHERE singleton;UPDATE public.monitored_mailboxes SET active=false,updated_at=clock_timestamp(),config=config||jsonb_build_object('containment','uid632-operation-completeness-repair-477') WHERE mailbox_key='pdc_pmb_email';UPDATE public.pdc_monitor_stage_activation_writers SET active=false,revoked_at=coalesce(revoked_at,clock_timestamp()) WHERE user_id='69846ef4-a74c-4569-9e35-376cf0837888'::uuid;UPDATE public.pdc_email_monitor_status SET running_status='stopped',gateway_instance_id=null,last_finished_at=clock_timestamp(),last_error_code='uid632_operation_completeness_repair',updated_at=clock_timestamp() WHERE singleton;
CREATE TABLE public.pdc_uid632_containment_receipts_477(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid632-operation-completeness-repair-477'),provider_uid text NOT NULL CHECK(provider_uid='imap_uid:632'),stock_number text NOT NULL CHECK(stock_number='13000776'),job_card_number text NOT NULL CHECK(job_card_number='J139125495'),observed_imported_operations integer NOT NULL CHECK(observed_imported_operations=8),source_pdf_operations integer NOT NULL CHECK(source_pdf_operations=22),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid632_containment_receipts_477 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid632_containment_receipts_477 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid632_containment_receipts_477(action_key,provider_uid,stock_number,job_card_number,observed_imported_operations,source_pdf_operations) VALUES('uid632-operation-completeness-repair-477','imap_uid:632','13000776','J139125495',8,22);
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827027000','477_contain_uid632_operation_completeness',ARRAY['Disable mailbox, writer and automatic email mutation after the one-shot run','Record that UID632 transport succeeded but 8 of 22 source operations were imported and completeness remediation remains mandatory','Preserve receipts and source attachment; Production untouched']);COMMIT;
